    40→/**
    41→ * Utility class which provides convenient methods for repo managing.
    42→ * @author Andrej Istomin (andrej.istomin.ikeen@gmail.com)
    43→ * @version $Id: ca443b1f988caccf98dd87503a1763f012839b21 $
    44→ */
    45→public final class RepoRule implements TestRule {
    46→
    47→    @Override
    48→    public Statement apply(final Statement statement,
    49→        final Description description) {
    50→        return new Statement() {
    51→            @Override
    52→            // @checkstyle IllegalThrowsCheck (1 line)
    53→            public void evaluate() throws Throwable {
    54→                statement.evaluate();
    55→            }
    56→        };
    57→    }
    58→
    59→    /**
    60→     * Create new repo for tests.
    61→     * @param repos Repos
    62→     * @return Repo
    63→     * @throws IOException If error occurred.
    64→     */
    65→    public Repo repo(final Repos repos) throws IOException {
    66→        final Repos.RepoCreate settings = new Repos.RepoCreate(
    67→            "foo",
    68→            false
    69→        ).withAutoInit(true);
    70→        int attempts = 0;
    71→        Repo repo = null;
    72→        while (repo == null) {
    73→            final Repos.RepoCreate request = settings.withName(
    74→                RandomStringUtils.randomAlphanumeric(Tv.TWENTY)
    75→            );
    76→            try {
    77→                repo = repos.create(request);
    78→            } catch (final AssertionError ex) {
    79→                Logger.warn(
    80→                    this, "Create repository failed. Message: %s",
    81→                    ex.getMessage()
    82→                );
    83→                ++attempts;
    84→                if (attempts > Tv.FIVE) {
    85→                    throw new IllegalStateException(
    86→                        String.format(
    87→                            "Failed to created repository %s",
    88→                            request.name()
    89→                        ),
    90→                        ex
    91→                    );
    92→                }
    93→            }
    94→        }
    95→        return repo;
    96→    }
    97→}
